BEGIN;

-- Lock the target slot row so concurrent transactions cannot read it FOR UPDATE
SELECT id, status 
FROM appointment_slots
WHERE id = 'slot_98234'
  AND status = 'AVAILABLE'
FOR UPDATE;

-- If the query returns a row, perform the update and write the reservation
UPDATE appointment_slots
SET status = 'BOOKED',
    customer_id = 'cust_44120',
    updated_at = NOW()
WHERE id = 'slot_98234';

INSERT INTO appointments (slot_id, customer_id, service_id, created_at)
VALUES ('slot_98234', 'cust_44120', 'srv_haircut', NOW());

COMMIT;

import { Pool, PoolClient } from 'pg';

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

interface BookingRequest {
  staffId: string;
  customerId: string;
  startTime: string; // ISO string
  endTime: string;   // ISO string
}

export async function createAppointment(req: BookingRequest) {
  const client: PoolClient = await pool.connect();

  try {
    await client.query('BEGIN');

    const insertQuery = `
      INSERT INTO staff_appointments (staff_id, customer_id, booking_period)
      VALUES ($1, $2, tsrange($3, $4, '[)'))
      RETURNING id, staff_id, customer_id, booking_period;
    `;

    const result = await client.query(insertQuery, [
      req.staffId,
      req.customerId,
      req.startTime,
      req.endTime,
    ]);

    await client.query('COMMIT');
    return { success: true, booking: result.rows[0] };
  } catch (error: any) {
    await client.query('ROLLBACK');

    // PostgreSQL error code 23P01 is exclusion_violation
    if (error.code === '23P01') {
      return {
        success: false,
        error: 'The requested time slot was just taken by another client. Please choose another time.',
      };
    }

    console.error('Failed to create appointment:', error);
    throw new Error('Database transaction failed.');
  } finally {
    client.release();
  }
}
